def _source_for(city_slug: str, key: str, default: PlaceSource) -> PlaceSource:
    return INDIVIDUAL_SOURCES.get((city_slug, key), default)

@dataclass(frozen=True, slots=True)
class ExpansionCity:
    slug: str
    name: str
    category_labels: dict[str, str]
    places: tuple[Place, ...]
    routes: tuple[RoutePlan, ...]

def _distance_km(a: Place, b: Place) -> float:
    lat1, lat2 = radians(a.latitude), radians(b.latitude)
    delta_lat = lat2 - lat1
    delta_lon = radians(b.longitude - a.longitude)
    haversine = sin(delta_lat / 2) ** 2 + (
        cos(lat1) * cos(lat2) * sin(delta_lon / 2) ** 2
    )
    return 2 * 6371.0088 * asin(sqrt(haversine))


def _compile_city(item: list) -> ExpansionCity:
    slug, name, url, specs = item
    source = PlaceSource(f"Туристический ресурс — {name}", url, CHECKED_AT)
    places = tuple(
        Place(
            f"{slug}-{key}", title, category,
            summary + ". Актуальные часы и условия уточняйте у организатора.",
            emoji, district, 45 if category in ("sights", "unusual") else
            (100 if category == "museums" else 70),
            category not in ("museums", "family"),
            latitude, longitude, _source_for(slug, key, source),
            tuple(dict.fromkeys(
                (category, "архитектура" if category == "sights" else
                 "прогулка" if category == "parks" else "музей" if category == "museums"
                 else "необычное", "с детьми" if category != "unusual" else "история",
                 "бесплатно" if category not in ("museums", "family") else "культура")
            )),
        )
        for key, title, category, latitude, longitude, district, summary, emoji in specs
    )
    by_cat = {category: [i for i, p in enumerate(places) if p.category == category]
              for category in CATEGORY_LABELS}
    lists = [
        ("first", "Первое знакомство", [0, 1, 2, 3]),
        ("historic", "Исторические места", by_cat["sights"][:4]),
        ("museums", "Музейный день", by_cat["museums"][:4]),
        ("walk", "Парки и улицы", by_cat["parks"][:4]),
        ("family", "Семейная прогулка",
         [i for i, p in enumerate(places) if "с детьми" in p.tags][:4]),
    ]
    routes = []
    for key, title, indexes in lists:
        if len(indexes) < 2:
            raise ValueError(f"{slug}: insufficient route points for {key}")
        items = tuple(places[index] for index in indexes)
        straight = sum(
            _distance_km(a, b)
            for a, b in pairwise(items)
        )
        walking_distance_km = max(0.5, round(straight * 1.35 + 0.3, 1))
        estimated_duration = sum(p.visit_minutes for p in items) + ceil(
            walking_distance_km / 4.5 * 60
        ) + 20
        routes.append(RoutePlan(
            f"{slug}-{key}", f"{name}: {title}",
            "Прогулка по выбранным городским точкам. Расстояние и время "
            "приблизительны; проверьте реальные переходы по карте.",
            estimated_duration, walking_distance_km, tuple(p.slug for p in items),
        ))
    return ExpansionCity(slug, name, CATEGORY_LABELS, places, tuple(routes))

